18	
19	/**
20	 * Imperatively redirects the current document to the auth entry page, preserving
21	 * the current URL as the `redirect` target. Intended for hard-fail auth paths
22	 * (e.g. a refresh-token request returning 401 from a non-React context).
23	 *
24	 * No-ops when the user is already on an auth page or on a public page that
25	 * does not require authentication, unless `forceRedirect` is set.
26	 */
27	export function redirectOnAuthFailure(
28	  forceRedirect = false,
29	  options?: {
30	    redirect?: string | null;
31	    reason?: string | null;
32	  },
33	): void {
34	  const currentPath = window.location.pathname;
35	  const currentRedirectPath = `${window.location.pathname}${window.location.search}${window.location.hash}`;
36	
37	  // Already on auth page, nothing to do.
38	  if (currentPath.startsWith(ROUTES.AUTH)) {
39	    return;
40	  }
41	
42	  // Don't redirect if it's a public route (unless forced, e.g. public visibility is disallowed).
43	  if (!forceRedirect && isPublicRoute(currentPath)) {
44	    return;
45	  }
46	
47	  clearAccessToken();
48	  window.location.replace(
