2	import useCurrentUser from "@/hooks/useCurrentUser";
3	import { AUTH_REDIRECT_PARAM, buildAuthRoute, getSafeRedirectPath } from "@/utils/auth-redirect";
4	import { ROUTES } from "./routes";
