6	/**
7	 * Index-route gate mounted at `/`. Authenticated visitors fall through to the
8	 * nested Home page; unauthenticated visitors are redirected to `/explore`,
9	 * preserving the original query string and hash so bookmarks like `/?filter=foo`
10	 * keep working.
11	 */
12	export const LandingRoute = () => {
13	  const currentUser = useCurrentUser();
14	  const location = useLocation();
15	
16	  if (!currentUser) {
17	    return (
18	      <Navigate
19	        to={{
20	          pathname: ROUTES.EXPLORE,
21	          search: location.search,
22	          hash: location.hash,
23	        }}
24	        replace
25	      />
26	    );
27	  }
28	
29	  return <Outlet />;
30	};
31	
32	/**
33	 * Guard for routes that require an authenticated user. Unauthenticated visitors
34	 * are redirected to `/auth` with the original location preserved as the `redirect`
35	 * query parameter, so they return to the intended page after signing in.
36	 */
37	export const RequireAuthRoute = () => {
38	  const currentUser = useCurrentUser();
39	  const location = useLocation();
40	
41	  if (!currentUser) {
42	    const redirect = `${location.pathname}${location.search}${location.hash}`;
43	    return <Navigate to={buildAuthRoute({ redirect })} replace />;
44	  }
45	
46	  return <Outlet />;
47	};
48	
49	/**
50	 * Guard for guest-only routes (sign-in and sign-up). Already-authenticated users
51	 * are redirected to the requested `redirect` target (when safe) or to `/`.
52	 *
53	 * The OAuth callback route (`/auth/callback`) intentionally opts out of this guard:
54	 * an authenticated session in another tab must not prevent the callback from
55	 * consuming its one-time OAuth state and completing the in-flight sign-in.
56	 */
57	export const RequireGuestRoute = () => {
58	  const currentUser = useCurrentUser();
59	  const [searchParams] = useSearchParams();
60	
61	  if (currentUser) {
62	    const redirectTarget = getSafeRedirectPath(searchParams.get(AUTH_REDIRECT_PARAM));
63	    return <Navigate to={redirectTarget || ROUTES.HOME} replace />;
64	  }
65	
66	  return <Outlet />;
67	};
